def save(self):
        failed = False
        if self.order_questions_form:
            if not self.order_questions_form.is_valid():
                failed = True
            else:
                checkoutsession = self.order_question_container if isinstance(self.order_question_container, CheckoutSession) else None
                order = self.order_question_container if isinstance(self.order_question_container, Order) else None
                for k, v in self.order_questions_form.cleaned_data.items():
                    if k.startswith('question_'):
                        field = self.order_questions_form.fields[k]
                        if hasattr(field, 'answer'):
                            # We already have a cached answer object, so we don't
                            # have to create a new one
                            if v == '' or v is None or (isinstance(field, forms.FileField) and v is False) \
                                    or (isinstance(v, QuerySet) and not v.exists()):
                                if field.answer.file:
                                    field.answer.file.delete()
                                field.answer.delete()
                            else:
                                self._save_to_answer(field, field.answer, v)
                                field.answer.save()
                        elif v != '' and v is not None:
                            self._upsert_answer(
                                field, v,
                                checkoutsession=checkoutsession,
                                order=order,
                                question=field.question,
                            )

        for form in self.forms:
            meta_info = form.pos.meta_info_data
            cartposition = form.pos if isinstance(form.pos, CartPosition) else None
            orderposition = form.pos if isinstance(form.pos, OrderPosition) else None
            # Every form represents a CartPosition or OrderPosition with questions attached
            if not form.is_valid():
                failed = True
            else:
                if form.cleaned_data.get('saved_id'):
                    prof = AttendeeProfile.objects.filter(
                        customer=self.cart_customer, pk=form.cleaned_data.get('saved_id')
                    ).first() or AttendeeProfile(customer=getattr(self, 'cart_customer', None))
                else:
                    prof = AttendeeProfile(customer=getattr(self, 'cart_customer', None))

                # This form was correctly filled, so we store the data as
                # answers to the questions / in the CartPosition object
                for k, v in form.cleaned_data.items():
                    if k in ('save', 'saved_id'):
                        continue
                    elif k == 'attendee_name_parts':
                        form.pos.attendee_name_parts = v if v else None
                        prof.attendee_name_parts = form.pos.attendee_name_parts
                        prof.attendee_name_cached = form.pos.attendee_name
                    elif k in ('attendee_email', 'company', 'street', 'zipcode', 'city', 'country', 'state'):
                        v = v if v != '' else None
                        setattr(form.pos, k, v)
                        setattr(prof, k, v)
                    elif k == 'requested_valid_from':
                        if isinstance(v, datetime.datetime):
                            form.pos.requested_valid_from = v
                        elif isinstance(v, datetime.date):
                            form.pos.requested_valid_from = make_aware(datetime.datetime.combine(
                                v,
                                datetime.time(hour=0, minute=0, second=0, microsecond=0)
                            ), self.request.event.timezone)
                        else:
                            form.pos.requested_valid_from = None
                    elif k.startswith('question_'):
                        field = form.fields[k]
                        if hasattr(field, 'answer'):
                            # We already have a cached answer object, so we don't
                            # have to create a new one
                            if v == '' or v is None or (isinstance(field, forms.FileField) and v is False) \
                                    or (isinstance(v, QuerySet) and not v.exists()):
                                if field.answer.file:
                                    field.answer.file.delete()
                                field.answer.delete()
                            else:
                                self._save_to_answer(field, field.answer, v)
                                field.answer.save()

                                answer_dict = self._build_answer_dict(field, field.answer, k)
                                prof.store_answer(answer_dict)
                        elif v != '' and v is not None:
                            answer = self._upsert_answer(
                                field, v,
                                cartposition=cartposition,
                                orderposition=orderposition,
                                question=field.question,
                            )

                            answer_dict = self._build_answer_dict(field, answer, k)
                            prof.store_answer(answer_dict)

                    else:
                        field = form.fields[k]

                        meta_info.setdefault('question_form_data', {})
                        if v is None:
                            if k in meta_info['question_form_data']:
                                del meta_info['question_form_data'][k]
                        else:
                            meta_info['question_form_data'][k] = v

                        answer_dict = {
                            'field_name': k,
                            'field_label': str(field.label),
                            'value': str(v),
                            'question_type': None,
                            'question_identifier': None,
                        }
                        prof.store_answer(answer_dict)

            form.pos.meta_info = json.dumps(meta_info)
            form.pos.save()

            if form.cleaned_data.get('save') and not failed:
                prof.save()
                self.cart_session[f'saved_attendee_profile_{form.pos.pk}'] = prof.pk

        return not failed

def save(self, commit=True):
        instance = super().save(commit)

        try:
            current_domain_assignment = instance.alternative_domain_assignment
        except AlternativeDomainAssignment.DoesNotExist:
            current_domain_assignment = None
        if self.cleaned_data['domain'] and not hasattr(instance, 'domain'):
            domain = self.instance.organizer.domains.get(mode=KnownDomain.MODE_ORG_ALT_DOMAIN, domainname=self.cleaned_data["domain"])
            AlternativeDomainAssignment.objects.update_or_create(
                event=instance,
                defaults={
                    "domain": domain,
                }
            )
            instance.cache.clear()
        elif current_domain_assignment:
            current_domain_assignment.delete()
            instance.cache.clear()

        return instance

def save(self, commit=True):
        objs = list(self.queryset)
        fields = set()

        for k in self.fields:
            cb_val = self.prefix + k
            if cb_val not in self.data.getlist('_bulk'):
                continue

            fields.add(k)
            if k == 'itemvars':
                selected_items = set(list(self.event.items.filter(id__in=[
                    i.split('-')[0] for i in self.cleaned_data['itemvars']
                ])))
                selected_variations = list(ItemVariation.objects.filter(item__event=self.event, id__in=[
                    i.split('-')[1] for i in self.cleaned_data['itemvars'] if '-' in i
                ]))
                for obj in objs:
                    obj.items.set(selected_items)
                    obj.variations.set(selected_variations)
            else:
                for obj in objs:
                    setattr(obj, k, self.cleaned_data[k])

        fields = [f for f in fields if f != 'itemvars']
        if fields:
            Quota.objects.bulk_update(objs, fields, 200)

def save(self, commit=True):
        instance = super().save(commit)
        self.meta_fields = []
